/**
 * @fileoverview Prefers object spread property over Object.assign
 * @author Sharmila Jesupaul
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/prefer-object-spread");
const RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const languageOptions = {
	ecmaVersion: 2018,
	sourceType: "module",
};

const ruleTester = new RuleTester({ languageOptions });

ruleTester.run("prefer-object-spread", rule, {
	valid: [
		"Object.assign()",
		"let a = Object.assign(a, b)",
		"Object.assign(a, b)",
		"let a = Object.assign(b, { c: 1 })",
		"const bar = { ...foo }",
		"Object.assign(...foo)",
		"Object.assign(foo, { bar: baz })",
		"Object.assign({}, ...objects)",
		"foo({ foo: 'bar' })",
		`
        const Object = {};
        Object.assign({}, foo);
        `,
		`
        Object = {};
        Object.assign({}, foo);
        `,
		`
        const Object = {};
        Object.assign({ foo: 'bar' });
        `,
		`
        Object = {};
        Object.assign({ foo: 'bar' });
        `,
		`
        const Object = require('foo');
        Object.assign({ foo: 'bar' });
        `,
		`
        import Object from 'foo';
        Object.assign({ foo: 'bar' });
        `,
		`
        import { Something as Object } from 'foo';
        Object.assign({ foo: 'bar' });
        `,
		`
        import { Object, Array } from 'globals';
        Object.assign({ foo: 'bar' });
        `,
		"globalThis.Object.assign({}, foo)",
		{
			code: "globalThis.Object.assign({}, { foo: 'bar' })",
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "globalThis.Object.assign({}, baz, { foo: 'bar' })",
			languageOptions: { ecmaVersion: 2017 },
		},
		{
			code: `
                var globalThis = foo;
                globalThis.Object.assign({}, foo)
                `,
			languageOptions: { ecmaVersion: 2020 },
		},
		{
			code: "class C { #assign; foo() { Object.#assign({}, foo); } }",
			languageOptions: { ecmaVersion: 2022 },
		},

		// ignore Object.assign() with > 1 arguments if any of the arguments is an object expression with a getter/setter
		"Object.assign({ get a() {} }, {})",
		"Object.assign({ set a(val) {} }, {})",
		"Object.assign({ get a() {} }, foo)",
		"Object.assign({ set a(val) {} }, foo)",
		"Object.assign({ foo: 'bar', get a() {}, baz: 'quux' }, quuux)",
		"Object.assign({ foo: 'bar', set a(val) {} }, { baz: 'quux' })",
		"Object.assign({}, { get a() {} })",
		"Object.assign({}, { set a(val) {} })",
		"Object.assign({}, { foo: 'bar', get a() {} }, {})",
		"Object.assign({ foo }, bar, {}, { baz: 'quux', set a(val) {}, quuux }, {})",
	],

	invalid: [
		{
			code: "Object.assign({}, foo)",
			output: "({ ...foo})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign  ({}, foo)",
			output: "({ ...foo})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign({}, { foo: 'bar' })",
			output: "({ foo: 'bar'})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign({}, baz, { foo: 'bar' })",
			output: "({ ...baz, foo: 'bar'})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign({}, { foo: 'bar', baz: 'foo' })",
			output: "({ foo: 'bar', baz: 'foo'})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign({ foo: 'bar' }, baz)",
			output: "({foo: 'bar', ...baz})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// Many args
		{
			code: "Object.assign({ foo: 'bar' }, cats, dogs, trees, birds)",
			output: "({foo: 'bar', ...cats, ...dogs, ...trees, ...birds})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		{
			code: "Object.assign({ foo: 'bar' }, Object.assign({ bar: 'foo' }, baz))",
			output: "({foo: 'bar', ...Object.assign({ bar: 'foo' }, baz)})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 31,
				},
			],
		},
		{
			code: "Object.assign({ foo: 'bar' }, Object.assign({ bar: 'foo' }, Object.assign({}, { superNested: 'butwhy' })))",
			output: "({foo: 'bar', ...Object.assign({ bar: 'foo' }, Object.assign({}, { superNested: 'butwhy' }))})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 31,
				},
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 61,
				},
			],
		},

		// Mix spread in argument
		{
			code: "Object.assign({foo: 'bar', ...bar}, baz)",
			output: "({foo: 'bar', ...bar, ...baz})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// Object shorthand
		{
			code: "Object.assign({}, { foo, bar, baz })",
			output: "({ foo, bar, baz})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// Objects with computed properties
		{
			code: "Object.assign({}, { [bar]: 'foo' })",
			output: "({ [bar]: 'foo'})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// Objects with spread properties
		{
			code: "Object.assign({ ...bar }, { ...baz })",
			output: "({...bar, ...baz})",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// Multiline objects
		{
			code: `Object.assign({ ...bar }, {
                // this is a bar
                foo: 'bar',
                baz: "cats"
            })`,
			output: `({...bar, // this is a bar
                foo: 'bar',
                baz: "cats"})`,
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		{
			code: `Object.assign({
                boo: "lol",
                // I'm a comment
                dog: "cat"
             }, {
                // this is a bar
                foo: 'bar',
                baz: "cats"
            })`,
			output: `({boo: "lol",
                // I'm a comment
                dog: "cat", // this is a bar
                foo: 'bar',
                baz: "cats"})`,
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 1,
				},
			],
		},

		// HTML comment
		{
			code: `const test = Object.assign({ ...bar }, {
                <!-- html comment
                foo: 'bar',
                baz: "cats"
                --> weird
            })`,
			output: `const test = {...bar, <!-- html comment
                foo: 'bar',
                baz: "cats"
                --> weird
            }`,
			languageOptions: {
				sourceType: "script",
			},
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 14,
				},
			],
		},

		{
			code: `const test = Object.assign({ ...bar }, {
                foo: 'bar', // inline comment
                baz: "cats"
            })`,
			output: `const test = {...bar, foo: 'bar', // inline comment
                baz: "cats"}`,
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 14,
				},
			],
		},

		{
			code: `const test = Object.assign({ ...bar }, {
                /**
                 * foo
                 */
                foo: 'bar',
                baz: "cats"
            })`,
			output: `const test = {...bar, /**
                 * foo
                 */
                foo: 'bar',
                baz: "cats"}`,
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 14,
				},
			],
		},

		{
			code: "const result = doSomething()\nObject.assign({}, myData)",
			output: "const result = doSomething()\n;({ ...myData})",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "let a = foo + Object.assign({}, bar)",
			output: "let a = foo + ({ ...bar})",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "let foo = function() {};\nfoo\nObject.assign({}, bar)",
			output: "let foo = function() {};\nfoo\n;({ ...bar})",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "foo\nObject.assign({ foo: bar })",
			output: "foo\n;({foo: bar})",
			errors: [
				{
					messageId: "useLiteralMessage",
				},
			],
		},
		{
			code: "foo();\nObject.assign({}, bar)",
			output: "foo();\n({ ...bar})",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "const x = [1]\nObject.assign({}, bar)",
			output: "const x = [1]\n;({ ...bar})",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "foo\nObject.assign({}, bar).doSomething()",
			output: "foo\n;({ ...bar}).doSomething()",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		{
			code: "foo\nObject.assign({}, bar), 2",
			output: "foo\n;({ ...bar}), 2",
			errors: [
				{
					messageId: "useSpreadMessage",
				},
			],
		},
		/*
		 * This is a special case where Object.assign is called with a single argument
		 * and that argument is an object expression. In this case we warn and display
		 * a message to use an object literal instead.
		 */
		{
			code: "Object.assign({})",
			output: "({})",
			errors: [
				{
					messageId: "useLiteralMessage",
					line: 1,
					column: 1,
				},
			],
		},
		{
			code: "Object.assign({ foo: bar })",
			output: "({foo: bar})",
			errors: [
				{
					messageId: "useLiteralMessage",
					line: 1,
					column: 1,
				},
			],
		},

		{
			code: `
                const foo = 'bar';
                Object.assign({ foo: bar })
            `,
			output: `
                const foo = 'bar';
                ({foo: bar})
            `,
			errors: [
				{
					messageId: "useLiteralMessage",
					line: 3,
					column: 17,
				},
			],
		},

		{
			code: `
                foo = 'bar';
                Object.assign({ foo: bar })
            `,
			output: `
                foo = 'bar';
                ({foo: bar})
            `,
			errors: [
				{
					messageId: "useLiteralMessage",
					line: 3,
					column: 17,
				},
			],
		},

		{
			code: "let a = Object.assign({})",
			output: "let a = {}",
			errors: [
				{
					messageId: "useLiteralMessage",
					line: 1,
					column: 9,
				},
			],
		},
		{
			code: "let a = Object.assign({}, a)",
			output: "let a = { ...a}",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 9,
				},
			],
		},
		{
			code: "let a = Object.assign   ({}, a)",
			output: "let a = { ...a}",
			errors: [
				{
					messageId: "useSpreadMessage",
					line: 1,
					column: 9,
				},
			],
		},
		{
